class SnapshotManager:
    """Manages dataset snapshots for version control."""
    def __init__(self):
        self.snapshots: Dict[str, pd.DataFrame] = {}
        self.lock = threading.Lock()

    def save_snapshot(self, df: pd.DataFrame) -> str:
        snapshot_id = str(uuid.uuid4())
        with self.lock:
            self.snapshots[snapshot_id] = df.copy()
        return snapshot_id

    def load_snapshot(self, snapshot_id: str) -> Optional[pd.DataFrame]:
        with self.lock:
            return self.snapshots.get(snapshot_id)

    def delete_snapshot(self, snapshot_id: str):
        with self.lock:
            if snapshot_id in self.snapshots:
                del self.snapshots[snapshot_id]


