        self._lock = threading.Lock()

    def record_change(self, user_id: str, action: str, details: Dict[str, Any], dataset_id: str = None):
        with self._lock:
            record = ChangeRecord(
                id=str(uuid.uuid4()),
                user_id=user_id,
                timestamp=datetime.utcnow().isoformat(),
                action=action,
                details=details
            )
            self.history.append(record)
            if dataset_id:
                self._snapshot_dataset(dataset_id)

    def _snapshot_dataset(self, dataset_id: str):
        # Simplified: store latest version only (in production, use versioned storage)
        if dataset_id not in self.snapshots:
            self.snapshots[dataset_id] = {}
        # In real system, would store multiple versions
        self.snapshots[dataset_id]["latest"] = {
            "timestamp": datetime.utcnow().isoformat(),
            "history_index": len(self.history) - 1
        }

    def get_history(self, dataset_id: str = None) -> List[ChangeRecord]:
        with self._lock:
            if dataset_id:
                return [r for r in self.history if r.details.get("dataset_id") == dataset_id]
