class DatasetManager:
    """Manages dataset state, versioning, and hashing."""

    def __init__(self):
        self.datasets: Dict[str, pd.DataFrame] = {}
        self.dataset_names: Dict[str, str] = {}  # id -> name
        self.dataset_history: Dict[str, List[ChangeRecord]] = {}
        self._lock = threading.RLock()

    def _hash_dataframe(self, df: pd.DataFrame) -> str:
        """Generate stable hash for DataFrame content."""
        try:
            # Use SHA-256 of CSV representation (with sorted columns for determinism)
            csv_str = df.to_csv(index=False, encoding='utf-8')
            return hashlib.sha256(csv_str.encode('utf-8')).hexdigest()[:16]
        except Exception:
            return "hash_error"

    def import_dataset(self, data: Union[pd.DataFrame, str], name: str, user_id: str) -> str:
        """Import a dataset (DataFrame or file path). Returns dataset ID."""
        with self._lock:
            dataset_id = str(uuid.uuid4())

            if isinstance(data, pd.DataFrame):
                df = data.copy()
            elif isinstance(data, str):
                df = self._load_from_file(data)
            else:
                raise ValueError("Data must be a DataFrame or file path")

            self.datasets[dataset_id] = df
            self.dataset_names[dataset_id] = name

            # Record import change
            change = ChangeRecord(
                change_id=str(uuid.uuid4()),
                timestamp=datetime.utcnow().isoformat() + "Z",
                user_id=user_id,
                change_type=ChangeType.DATA_IMPORT,
                description=f"Imported dataset '{name}'",
                dataset_hash_before=None,
                dataset_hash_after=self._hash_dataframe(df),
                metadata={"filename": data if isinstance(data, str) else "DataFrame"}
            )
            self.dataset_history[dataset_id] = [change]

            return dataset_id

    def _load_from_file(self, filepath: str) -> pd.DataFrame:
        """Load dataset from file (CSV, Excel, JSON)."""
        ext = os.path.splitext(filepath)[1].lower()

        if ext == ".csv":
            return pd.read_csv(filepath)
        elif ext in [".xlsx", ".xls"]:
            return pd.read_excel(filepath)
        elif ext == ".json":
            with open(filepath, 'r') as f:
                data = json.load(f)
            if isinstance(data, list):
                return pd.DataFrame(data)
            elif isinstance(data, dict):
                return pd.json_normalize(data)
            else:
                raise ValueError("Unsupported JSON structure")
        else:
            raise ValueError(f"Unsupported file format: {ext}")

    def get_dataset(self, dataset_id: str) -> pd.DataFrame:
        with self._lock:
            return self.datasets.get(dataset_id)

    def update_dataset(self, dataset_id: str, new_df: pd.DataFrame, user_id: str, 
                       change_type: ChangeType, description: str, metadata: Dict = None) -> bool:
        with self._lock:
            if dataset_id not in self.datasets:
                return False

            old_df = self.datasets[dataset_id]
            old_hash = self._hash_dataframe(old_df)

            self.datasets[dataset_id] = new_df.copy()
            new_hash = self._hash_dataframe(new_df)

            change = ChangeRecord(
                change_id=str(uuid.uuid4()),
                timestamp=datetime.utcnow().isoformat() + "Z",
                user_id=user_id,
                change_type=change_type,
                description=description,
                dataset_hash_before=old_hash,
                dataset_hash_after=new_hash,
                metadata=metadata or {}
            )
            self.dataset_history[dataset_id].append(change)
            return True

    def get_history(self, dataset_id: str) -> List[ChangeRecord]:
        with self._lock:
            return self.dataset_history.get(dataset_id, [])

    def get_all_datasets(self) -> Dict[str, str]:
        with self._lock:
            return dict(self.dataset_names)


